create or replace function public.is_qualifying_return_visit(p_user_id uuid,p_location_id uuid,p_check_in_at timestamptz default now(),p_check_in_id uuid default null) returns boolean language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ declare v_last_check timestamptz; v_today integer; v_cap integer:=5; v_same_visit_reward boolean; begin if p_user_id is null or p_location_id is null then return false; end if; if p_check_in_id is not null then select exists(select 1 from public.point_transactions pt where pt.user_id=p_user_id and pt.reason='check_in' and pt.reference_id=p_check_in_id) into v_same_visit_reward; if v_same_visit_reward then return false; end if; end if; select max(checked_in_at) into v_last_check from public.check_ins where user_id=p_user_id and location_id=p_location_id and checked_in_at < p_check_in_at and (p_check_in_id is null or id<>p_check_in_id); if v_last_check is not null and p_check_in_at-v_last_check < interval '60 minutes' then return false; end if; select count(*)::integer into v_today from public.point_transactions where user_id=p_user_id and reason in ('check_in','review') and created_at >= date_trunc('day',p_check_in_at) and created_at < date_trunc('day',p_check_in_at)+interval '1 day'; return v_today < v_cap; end; $function$;

create or replace function public.record_gamification_activity(p_activity text,p_reference_id uuid default null) returns jsonb language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ declare u uuid:=auth.uid(); today date:=current_date; s public.user_streaks; awarded_points integer; total_points integer:=0; new_level integer:=1; activity text:=lower(trim(coalesce(p_activity,''))); inserted boolean:=false; challenge_reward integer:=0; v_location uuid; v_checkin uuid; v_checkin_at timestamptz; v_eligible boolean:=true; begin if u is null then raise exception 'Authentication required'; end if; if activity not in ('check_in','verification','review','favorite','qr_scan','route_completed','route_stop_completed','social_post','social_contribution','share','event_rsvp','contest_entry','location_diversity','community','challenge_completed') then raise exception 'Unsupported gamification activity: %',activity; end if; if activity in ('check_in','review') then perform pg_advisory_xact_lock(hashtextextended('kleenest:progression:'||u::text,0)); if activity='check_in' then select c.location_id,c.checked_in_at into v_location,v_checkin_at from public.check_ins c where c.id=p_reference_id and c.user_id=u; v_checkin:=p_reference_id; else select r.location_id,r.check_in_id,c.checked_in_at into v_location,v_checkin,v_checkin_at from public.reviews r left join public.check_ins c on c.id=r.check_in_id and c.user_id=u where r.id=p_reference_id and r.user_id=u; end if; if v_location is null or v_checkin_at is null then v_eligible:=false; else v_eligible:=public.is_qualifying_return_visit(u,v_location,v_checkin_at,v_checkin); end if; if not v_eligible then return jsonb_build_object('activity',activity,'awarded_points',0,'new_activity',false,'reason','progression_not_eligible'); end if; end if; select * into s from public.user_streaks where user_id=u for update; if not found then insert into public.user_streaks(user_id,current_streak,longest_streak,last_activity_date,streak_started_at) values(u,1,1,today,now()) returning * into s; elsif s.last_activity_date=today then update public.user_streaks set updated_at=now() where user_id=u returning * into s; elsif s.last_activity_date=today-1 then update public.user_streaks set current_streak=current_streak+1,longest_streak=greatest(longest_streak,current_streak+1),last_activity_date=today,updated_at=now() where user_id=u returning * into s; else update public.user_streaks set current_streak=1,longest_streak=greatest(longest_streak,1),last_activity_date=today,streak_started_at=now(),updated_at=now() where user_id=u returning * into s; end if; if activity='challenge_completed' then select greatest(coalesce(reward_points,0),0) into challenge_reward from public.progression_challenges where id=p_reference_id and enabled=true; if not found then raise exception 'Challenge is unavailable'; end if; awarded_points:=challenge_reward; else awarded_points:=case activity when 'check_in' then 10 when 'verification' then 15 when 'review' then 25 when 'favorite' then 5 when 'qr_scan' then 5 when 'route_completed' then 25 when 'route_stop_completed' then 5 when 'social_post' then 5 when 'social_contribution' then 5 when 'share' then 3 when 'event_rsvp' then 3 when 'contest_entry' then 5 when 'location_diversity' then 10 else 5 end; end if; if s.current_streak>=7 then awarded_points:=awarded_points+5; end if; if p_reference_id is not null then insert into public.point_transactions(user_id,points,reason,reference_id) values(u,awarded_points,activity,p_reference_id) on conflict (user_id,reason,reference_id) where reference_id is not null do nothing; inserted:=found; else insert into public.point_transactions(user_id,points,reason) values(u,awarded_points,activity); inserted:=true; end if; select coalesce(sum(points),0)::integer into total_points from public.point_transactions where user_id=u; select coalesce((select level from public.level_definitions where min_points<=total_points and (max_points is null or total_points<=max_points) order by level desc limit 1),1) into new_level; update public.profiles set points=total_points,level=new_level,streak=s.current_streak,updated_at=now() where id=u; perform public.evaluate_user_badges(u); return jsonb_build_object('activity',activity,'awarded_points',case when inserted then awarded_points else 0 end,'points',total_points,'level',new_level,'current_streak',s.current_streak,'longest_streak',s.longest_streak,'new_activity',inserted); end; $function$;

comment on function public.record_gamification_activity(text,uuid) is 'Authoritative gamification reward boundary. Check-in/review rewards are serialized per user and require a qualifying return visit plus shared daily cap; underlying reviews/check-ins remain recordable.';
